#include <stddef.h>
#include <stdint.h>

bool decodeFrame(const uint8_t* frame, size_t length,
                 uint16_t& millivolts) {
  if (frame == nullptr || length != 4 || frame[0] != 0xA5) {
    return false;
  }
  if ((frame[1] ^ frame[2]) != frame[3]) return false;
  millivolts = (uint16_t(frame[1]) << 8) | frame[2];
  return true;
}
